<script setup lang="ts">
import type {LiveContext} from './v6LiveTypes'
import {vRememberDisclosure} from './rememberDisclosure'
defineProps<{value:LiveContext}>()
const fmt=(n:number|null|undefined,d=2)=>n==null?'—':n.toLocaleString('zh-TW',{maximumFractionDigits:d})
const sign=(n:number,d=2)=>`${n>0?'+':''}${fmt(n,d)}`
const time=(s:string)=>s?.slice(0,19).replace('T',' ')
const state=(s:string)=>({ready:'最新盤中・可能延遲',closed:'已收盤',stale:'資料較舊・不當新訊號',already_reflected:'已在台股收盤前・不當新訊號'}[s]||s)
const safe=(s:string)=>/^https:\/\//.test(s)?s:undefined
</script>
