 <section class="live-context" aria-label="本次夜盤與海外即時情勢評估">
  <header><div><small>OVERNIGHT · MARKET CONTEXT</small><h3>本次夜盤與海外評估</h3><p>取價截止 {{time(value.captured_at)}}（台北） · 台股收盤 {{value.market_as_of}}</p></div><b>{{value.assessment.state}}</b></header>
  <p class="reading">{{value.assessment.reading}}</p>
  <p class="boundary">{{value.assessment.note}}</p>
